export function googleRemotePage(){return `<!doctype html><html lang="zh-Hans"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Google 远程授权</title><script src="/google-authorization/remote.js" defer></script><style>body{margin:0;background:#f4f5ef;color:#193b30;font:16px/1.6 system-ui}main{max-width:1080px;margin:24px auto;padding:20px}button{padding:10px 18px;border:0;border-radius:8px;background:#193b30;color:white;margin:6px 8px 6px 0;cursor:pointer}button:disabled{opacity:.5}canvas{width:100%;height:auto;border:1px solid #b8c9bd;background:white;display:block;touch-action:manipulation}#keyboard{position:fixed;width:1px;height:1px;opacity:0;pointer-events:none}#message{white-space:pre-wrap}a{color:#245e49}</style></head><body><main><h1>Google 远程授权</h1><p>私有 OAuth 入口 · 浏览器运行在临时 Codex 环境 · 最长 15 分钟</p><p>在下方的 Google 官方网页完成登录和验证，进入 BundleFoundry 后点击“保存并测试”。不记录密码、验证码、浏览器画面或键盘输入。</p><button id="start">打开远程浏览器</button><button id="finish" disabled>保存并测试</button><button id="cancel" disabled>关闭浏览器</button><p id="message" role="status" aria-live="polite">点击按钮打开浏览器。</p><canvas id="screen" width="1024" height="768" tabindex="0" aria-label="私有远程浏览器画面"></canvas><textarea id="keyboard" autocomplete="off" autocapitalize="off" spellcheck="false" aria-label="远程浏览器键盘"></textarea><p><a href="/">返回领取中心</a></p></main></body></html>`;}

export const googleRemoteScript=`
const screen=document.getElementById('screen'),keyboard=document.getElementById('keyboard'),message=document.getElementById('message');
let id=null,timer=null,queue=Promise.resolve(),committing=false;
const special=new Set(['Enter','Tab','Backspace','Delete','ArrowLeft','ArrowRight','ArrowUp','ArrowDown','Escape','Home','End']);
async function call(path,body){const response=await fetch(path,{credentials:'same-origin',...(body===undefined?{}:{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)})});const data=await response.json();if(!response.ok)throw Error(({forbidden:'请使用本站所有者身份登录。',browser_not_ready:'浏览器尚未准备好。',run_in_progress:'已有任务运行中，请稍后重试。',browser_authorization_not_saved:'浏览器尚未完成登录。',upstream_run_incomplete:'云端测试未通过，已保存的授权仍保留。',browser_action_incomplete:'浏览器操作暂未完成，请稍后重试。'})[data.error]||'操作暂未完成，请重试。');return data;}
function input(operation,extra={}){if(!id)return;queue=queue.then(()=>call('/api/google-browser/input',{id,operation,...extra})).catch(error=>{message.textContent=error.message;});}
async function refresh(){try{const state=await call('/api/google-browser/state');id=state.id;const interactive=state.phase==='interactive';document.getElementById('finish').disabled=!interactive;document.getElementById('cancel').disabled=!id||['closed','expired','committed'].includes(state.phase);if(state.frame){const image=new Image();image.onload=()=>screen.getContext('2d').drawImage(image,0,0,1024,768);image.src='data:image/jpeg;base64,'+state.frame;}if(state.phase==='starting')message.textContent=state.agent_online?'浏览器准备中…':'等待受保护的浏览器执行环境连接…';if(interactive)message.textContent=state.notice==='login_not_completed'?'尚未确认进入 BundleFoundry，请先完成 Google 登录。':'当前网页：'+(state.host||'准备中')+'。请在画面中登录；点击输入框后可使用键盘。';if(state.phase==='saving')message.textContent='正在核对账号、关闭浏览器并保存会话…';if(['closed','expired','committed'].includes(state.phase)&&!committing)screen.getContext('2d').clearRect(0,0,1024,768);if(state.phase==='error')message.textContent='浏览器启动未完成，请关闭后重新打开。';if(state.phase==='captured'&&!committing){committing=true;screen.getContext('2d').clearRect(0,0,1024,768);message.textContent='浏览器已关闭，正在加密保存并执行云端失效测试…';await call('/api/google-browser/commit',{});const test=await call('/api/google-browser/test',{});if(test.session_recovery_test?.site_session_valid_after_login!==true)throw Error('云端测试尚未通过。');message.textContent='云端失效测试通过：Google 会话已自动复用，BundleFoundry 账号与新登录会话已核实。';clearTimeout(timer);return;}}catch(error){message.textContent=error.message;if(committing){clearTimeout(timer);return;}}timer=setTimeout(refresh,1000);}
document.getElementById('start').addEventListener('click',async()=>{try{committing=false;const state=await call('/api/google-browser/start',{});id=state.id;clearTimeout(timer);refresh();}catch(error){message.textContent=error.message;}});
document.getElementById('finish').addEventListener('click',()=>input('finish'));
document.getElementById('cancel').addEventListener('click',()=>input('cancel'));
screen.addEventListener('click',event=>{const rect=screen.getBoundingClientRect();input('click',{x:Math.min(1023,Math.max(0,Math.floor((event.clientX-rect.left)*1024/rect.width))),y:Math.min(767,Math.max(0,Math.floor((event.clientY-rect.top)*768/rect.height)))});keyboard.focus();});
screen.addEventListener('wheel',event=>{event.preventDefault();input('scroll',{delta:Math.max(-2000,Math.min(2000,Math.round(event.deltaY)))});},{passive:false});
keyboard.addEventListener('keydown',event=>{if(event.ctrlKey||event.metaKey||event.altKey)return;if(special.has(event.key)){event.preventDefault();input('key',{key:event.key});}else if(event.key.length===1){event.preventDefault();input('text',{text:event.key});}});
keyboard.addEventListener('paste',event=>{event.preventDefault();const text=event.clipboardData.getData('text').slice(0,4096);if(text)input('text',{text});keyboard.value='';});
keyboard.addEventListener('input',()=>{const text=keyboard.value;keyboard.value='';if(text)input('text',{text:text.slice(0,4096)});});
`;
